   1 package security
   2 
   3 import (
   4     "cmp"
   5     "sort"
   6     "strconv"
   7 
   8     "charm.land/lipgloss/v2"
   9 
  10     "github.com/anthnel/devdesk/internal/remediation"
  11     "github.com/anthnel/devdesk/internal/scan"
  12     "github.com/anthnel/devdesk/internal/ui/datatable"
  13     "github.com/anthnel/devdesk/internal/ui/theme"
  14 )
  15 
  16 // DEVDESK-754 (SC2): "Group by fix" on the Misconfigurations tab. One row per
  17 // file and per fix: the key is the file, the rule (remediation.RuleKey, which
  18 // folds Trivy's two spellings) and the state of the built-in fix. The count is a
  19 // number of findings and nothing more: ctrl+o fixes one finding at a time, so a
  20 // group never promises to close anything.
  21 
  22 // noFileSubject is what the File column says for a finding that names no file,
  23 // which is what an image's misconfigurations do.
  24 const noFileSubject = "(image)"
  25 
  26 // misconfigGroups groups the misconfigurations of findings by file and by fix: one
  27 // group per (file, rule, state of the built-in fix). Worst severity first, then
  28 // the most findings, then the file, the rule and the state of the fix.
  29 func misconfigGroups(findings []scan.Finding, onDisk bool) []fixGroup {
  30     return groupMisconfigs(findings, func(f scan.Finding) fixStatus { return fixStatusOf(f, onDisk) })
  31 }
  32 
  33 // groupMisconfigs is misconfigGroups with the status of a finding given, so that
  34 // a test can give two findings of one rule reasons the catalog never produces.
  35 func groupMisconfigs(findings []scan.Finding, statusOf func(scan.Finding) fixStatus) []fixGroup {
  36     byKey := map[groupKey]*fixGroup{}
  37     var order []groupKey
  38     for _, f := range findings {
  39         if scan.Categorize(f) != scan.CategoryMisconfiguration {
  40             continue
  41         }
  42         status := statusOf(f)
  43         key := groupKey{File: f.File, Rule: remediation.RuleKey(f.ID), Fix: status.State}
  44         if status.State == fixBuiltInDeclined {
  45             key.Reason = status.Reason
  46         }
  47         g, ok := byKey[key]
  48         if !ok {
  49             g = &fixGroup{
  50                 Key:       key,
  51                 Misconfig: true,
  52                 Severity:  f.Severity,
  53                 Subject:   fileSubject(f.File),
  54                 Rule:      inlineText(f.ID),
  55                 Status:    status,
  56             }
  57             byKey[key] = g
  58             order = append(order, key)
  59         }
  60         if severityRank(f.Severity) > severityRank(g.Severity) {
  61             g.Severity = f.Severity
  62         }
  63         g.Members = append(g.Members, f)
  64     }
  65     groups := make([]fixGroup, 0, len(order))
  66     for _, key := range order {
  67         g := *byKey[key]
  68         g.Command = sharedCommand(g.Members)
  69         groups = append(groups, g)
  70     }
  71     sort.SliceStable(groups, func(i, j int) bool { return misconfigGroupLess(groups[i], groups[j]) })
  72     return groups
  73 }
  74 
  75 // fileSubject is the file as the row shows it: relative to the scanned directory,
  76 // on one line, with no control or bidi character from the scan.
  77 func fileSubject(file string) string {
  78     if file == "" {
  79         return noFileSubject
  80     }
  81     return inlineText(shortPaths(file, ""))
  82 }
  83 
  84 // sharedCommand is the command every member agrees on, "" when one has none, when
  85 // they differ, or when it is not plain words (runCommand decides all of that).
  86 func sharedCommand(members []scan.Finding) string {
  87     command := ""
  88     for i, f := range members {
  89         c, ok := runCommand(f)
  90         if !ok || i > 0 && c != command {
  91             return ""
  92         }
  93         command = c
  94     }
  95     return command
  96 }
  97 
  98 // misconfigGroupLess orders groups by worst severity, then the most findings, then
  99 // the file, the rule and the state of the fix. It reads the key, not the order of
 100 // the scan, so a reversed scan lists the same rows.
 101 func misconfigGroupLess(a, b fixGroup) bool {
 102     return cmp.Or(
 103         cmp.Compare(severityRank(b.Severity), severityRank(a.Severity)),
 104         cmp.Compare(len(b.Members), len(a.Members)),
 105         cmp.Compare(a.Subject, b.Subject),
 106         cmp.Compare(a.Key.File, b.Key.File),
 107         cmp.Compare(a.Key.Rule, b.Key.Rule),
 108         cmp.Compare(a.Key.Fix, b.Key.Fix),
 109         cmp.Compare(a.Key.Reason, b.Key.Reason),
 110     ) < 0
 111 }
 112 
 113 // misconfigGroupColumns describes the grouped list of the Misconfigurations tab:
 114 // Severity, File, Rule, Findings, Fix. Cells are plain text (Rule 122); only
 115 // Severity is coloured, and it is also its word. The file keeps its tail, which is
 116 // what tells two files apart.
 117 func misconfigGroupColumns() []datatable.Column[fixGroup] {
 118     return []datatable.Column[fixGroup]{
 119         {
 120             Title: "Severity", Sizing: datatable.SizingFixed, MinWidth: 10,
 121             Cell:  func(g fixGroup) string { return string(g.Severity) },
 122             Style: func(g fixGroup) lipgloss.Style { return theme.SeverityTextStyle(string(g.Severity)) },
 123             Less:  func(a, b fixGroup) bool { return severityRank(a.Severity) < severityRank(b.Severity) },
 124         },
 125         {
 126             Title: "File", Sizing: datatable.SizingContent, MinWidth: 14, MaxWidth: 40,
 127             TruncateHead: true,
 128             Cell:         func(g fixGroup) string { return g.Subject },
 129             Less:         func(a, b fixGroup) bool { return a.Subject < b.Subject },
 130         },
 131         {
 132             Title: "Rule", Sizing: datatable.SizingContent, MinWidth: 10, MaxWidth: 24,
 133             Cell: func(g fixGroup) string { return g.Rule },
 134             Less: func(a, b fixGroup) bool { return a.Rule < b.Rule },
