// This is the same act as writing a base image (phase C of §3.2) applied to a
// second class of finding, so it is the same key, the same confirmation that
// defaults to No, and the same write: the bytes at one located range and
// nothing else.
//
// What differs is that only **some** rules can be fixed. The catalog in
// internal/remediation is deliberately finite, and a rule outside it is not a
// failure — it is the case the MCP server covers by handing a calling agent the
// span and the wording. So ctrl+o greys out here far more often than it does on
// the Remediation tab, and that greying is what makes the boundary between the
// two paths visible instead of guessed at.

// ── Reasons (Rule 130) ───────────────────────────────────────────────────────

const (
	reasonNotMisconfigTab = "Only misconfigurations have a built-in fix"
	reasonFileNotOnDisk   = "This target is an image — its files are inside it, not on disk"
)

// ── Messages (Rule 109) ──────────────────────────────────────────────────────

// MisconfigFixPreparedMsg is the answer to computing the fix: the file as it
// would become, and what git says about it. It carries the bytes the
// confirmation is about, so the write that follows is that one.
type MisconfigFixPreparedMsg struct {
	Target string
	File   preparedWrite
	// Rule is the AVD id, which the verification re-scan is checked against.
	// Body is what the confirmation shows — the fix's title and the diff — and
	// the two are separate fields because one is read by a human and the other
	// compared against a later scan.
	Rule string
	Body string
	// Instance says which occurrence of the rule, for the same reason — see
	// instanceOf.
	Instance string
	// FindingFile is the file the finding points at, which the verification
	// looks in. It is File.File for every rule but the build context's, whose
	// fix edits the .dockerignore beside the Dockerfile it reports (§3.81).
	FindingFile string
	// Scope is what the verification looks for: the workload an edit clears for
	// every container, or the zero value for a fix of one occurrence
	// (DEVDESK-688).
	Scope remediation.Scope
	// Lines is the diff as the preview and the confirmation show it: markers,
	// sanitized, neither capped nor cut (DEVDESK-753).
	Lines []string
	Err   error
}

// MisconfigFixWrittenMsg reports the write. File is the file written,
// FindingFile the one the rule was reported in.
type MisconfigFixWrittenMsg struct {
	Target      string
	File        string
	FindingFile string
	Rule        string
	Instance    string
	Scope       remediation.Scope
	Err         error
}

// ── Availability ─────────────────────────────────────────────────────────────

// canFixMisconfig is the one computation behind the shortcut column and the
// handler (Rule 130). It answers in the order the user would ask: am I in the
// right place, is there a row, can its file be written at all, and is this rule
// one the catalog knows.
//
// The last question runs the fix itself. That is deliberate: a rule can be in
// the catalog and still decline this instance — a base image whose distribution
// cannot be identified, a stage that already sets a user — and greying out on
// "the catalog has an entry" while the handler then refuses would be exactly
// the two computations Rule 130 forbids.
func (m Model) canFixMisconfig() shortcut.Availability {
	if m.activeTab != TabMisconfig {
		return shortcut.Unavailable(reasonNotMisconfigTab)
	}
	// In the grouped list the findings table behind it still has a selection, and a
	// group is not one finding: the fix waits for a finding's detail.
	if m.state == StateResults && m.isGrouped() {
		return shortcut.Unavailable(reasonOpenTheGroup)
	}
	f, ok := m.subjectFinding()
	if !ok {
		return shortcut.Unavailable(reasonNoFinding)
	}
	if _, a := misconfigFixAvailability(f, m.targetOnDisk()); !a.Enabled() {
		return a
	}
	// What the stored preview knows, with no disk read (DEVDESK-753).
	return m.previewVerdict(f)
}

// misconfigFixAvailability is what canFixMisconfig answers for a finding once a
// row exists, and what the finding detail reads for its fix status, so the two
// cannot disagree (Rule 130). onDisk says whether the target is a directory:
// an image's files are inside it, where nothing can be written. It also returns
// the catalog rule, whenever the catalog has one, so a caller can say what the
// fix would do even where it cannot run.
func misconfigFixAvailability(f scan.Finding, onDisk bool) (remediation.Rule, shortcut.Availability) {
	rule, ok := remediation.FixFor(f)
	if !onDisk {
		return rule, shortcut.Unavailable(reasonFileNotOnDisk)
	}
	if !ok {
		return rule, shortcut.Unavailable(noFixReason(f))
	}
	// A refusal the finding alone settles (DEVDESK-688): greyed in advance, with
	// the reason the press of the key would give.
	if rule.Declines != nil {
		if reason := rule.Declines(f); reason != "" {
			return rule, shortcut.Unavailable(reason)
		}
	}
	// Reading the file here would be I/O on a path the header calls every
	// frame, so the declines that need the content are left to the Cmd and
	// reach the footer. What is settled here is everything the finding alone
	// can answer.
	return rule, shortcut.Availability{}
}

// noFixReason is why a finding with no fix in the catalog is refused: for a Pod
// Security finding, what the manifest is missing (DEVDESK-689); for anything
// else, the generic refusal. The fix is tried first, so a rule that has one never
// reaches the missing text.
func noFixReason(f scan.Finding) string {
	if text, ok := remediation.MissingFor(f); ok {
		return text
	}
	return remediation.ReasonNoFixForRule
}

// ── Preparing ────────────────────────────────────────────────────────────────

// prepareMisconfigFix starts the fix by computing it: nothing is asked of the
// user until the file has been read, rewritten and put to git, so the
// confirmation can state what it is about.
func (m Model) prepareMisconfigFix() (tea.Model, tea.Cmd) {
	if a := m.canFixMisconfig(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	f, _ := m.subjectFinding()
	return m, prepareMisconfigFixCmd(m.targetPath, f, m.scannedAt())
}

// prepareMisconfigFixCmd runs computeMisconfigFix off Update (Rule 110). The
// finding is copied in. scannedAt is when the result on screen was measured.
//
// A rule that declines here is not an error: it is an answer, and it reaches the
// footer as a warning rather than as a failure.
func prepareMisconfigFixCmd(target string, f scan.Finding, scannedAt time.Time) tea.Cmd {
	return func() tea.Msg { return computeMisconfigFix(target, f, scannedAt) }
}

// errDeclined carries a catalog refusal through the same channel as a failure,
// so the handler has one message to read, and tells the two apart by type rather
// than by inspecting a string.
type errDeclined struct{ reason string }

func (e errDeclined) Error() string { return e.reason }

// ── Confirming and writing ───────────────────────────────────────────────────

func (m Model) handleMisconfigFixPrepared(msg MisconfigFixPreparedMsg) (tea.Model, tea.Cmd) {
	if msg.Target != m.targetPath {
		return m, nil // an answer about a result no longer on screen
	}
	if d, ok := msg.Err.(errDeclined); ok {
		// Nothing failed: the catalog will not fix this instance, and says why.
		return m, m.footer.Warn(d.reason)
	}
	if msg.Err != nil {
		log.Printf("ERROR [security/misconfig] prepare fix: %s", withoutPath(msg.Err))
		return m, m.footer.Error("Could not prepare the fix — the file may have changed, check logs")
	}
	m.misconfigPending = &msg.File
	m.misconfigFinding = misconfigFindingRef{Rule: msg.Rule, Instance: msg.Instance, File: msg.FindingFile, Scope: msg.Scope}
	// Rule 104: the safe answer is the default — ConfirmModal opens on No.
	m.confirmModal = sharedcomponents.NewConfirmModal("Fix misconfiguration", misconfigConfirmationText(msg.File, msg.Body))
	return m, nil
}

// misconfigConfirmationText shows the diff itself, not a summary of it.
//
// A base image bump is one token replaced by another and reads as a sentence; a
// misconfiguration fix inserts a block, and no sentence conveys what is about to
// land in the file. What the user agrees to is the diff, so the diff is what the
// modal shows — followed by what git will and will not be able to undo.
func misconfigConfirmationText(f preparedWrite, body string) string {
	return body + "\n" + fmt.Sprintf("%s: %s\n", shownName(f.File), gitAdvice(f))
}

// shownName makes a file name, which the scanned repository chose, safe to put
// in the confirmation or the footer: no escape sequence, no control character,
// and one line.
func shownName(name string) string {
	return strings.ReplaceAll(withoutControlSpace(name), "\n", " ")
}

// handleMisconfigFixConfirmed runs the write the modal was about.
func (m Model) handleMisconfigFixConfirmed() (tea.Model, tea.Cmd) {
	file, ref := m.misconfigPending, m.misconfigFinding
	m.misconfigPending = nil
	m.misconfigFinding = misconfigFindingRef{}
	m.confirmModal = nil
	if file == nil {
		return m, nil
	}
	return m, writeMisconfigFixCmd(m.targetPath, ref, *file)
}

// errLeavesTarget is the refusal of a write whose path now leads out of the
// scanned directory: a link was put there after the preview.
var errLeavesTarget = errors.New("the file is now reached through a link that leaves the scanned directory")

func writeMisconfigFixCmd(target string, ref misconfigFindingRef, f preparedWrite) tea.Cmd {
	return func() tea.Msg {
		// The preview checked the path, and the content check below would pass for
		// a link to a file holding the same bytes: look again, as late as possible.
		var err error
		if staysInside(target, f.Path) {
			err = patch.WriteIfUnchanged(f.Path, f.Original, f.Updated)
		} else {
			err = errLeavesTarget
		}
		return MisconfigFixWrittenMsg{
			Target: target, File: f.File, FindingFile: ref.File,
			Rule: ref.Rule, Instance: ref.Instance, Scope: ref.Scope, Err: err,
		}
	}
}

